const birds=[{id:'robin',name:'European Robin',latin:'Erithacus rubecula',rarity:'Common',habitat:'Gardens & woodland',photo:'photo-1444464666168-49d633b86797',xp:25},{id:'kingfisher',name:'Common Kingfisher',latin:'Alcedo atthis',rarity:'Rare',habitat:'Rivers & wetlands',photo:'photo-1497206365907-f5e630693df0',xp:100},{id:'blue-tit',name:'Eurasian Blue Tit',latin:'Cyanistes caeruleus',rarity:'Uncommon',habitat:'Parks & woodland',photo:'photo-1452570053594-1b985d6ea890',xp:50},{id:'blackbird',name:'Common Blackbird',latin:'Turdus merula',rarity:'Common',habitat:'Gardens & parks',photo:'photo-1444464666168-49d633b86797',xp:25},{id:'sparrow',name:'House Sparrow',latin:'Passer domesticus',rarity:'Common',habitat:'Towns & gardens',photo:'photo-1452570053594-1b985d6ea890',xp:25}];
const $=s=>document.querySelector(s);let catches=[];try{catches=JSON.parse(localStorage.getItem('birdquest-v1')||'[]');if(!Array.isArray(catches))catches=[]}catch{}for(const c of catches){if(c.speciesData&&!birds.some(b=>b.id===c.bird))birds.push(c.speciesData)}let coords=null,recorder=null,stream=null,audioUrl=null,recording=false;const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const photo=b=>b.photo?`https://images.unsplash.com/${b.photo}?auto=format&fit=crop&w=650&q=80`:'bird-placeholder.svg';const fmt=d=>new Date(d).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'});function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),4000)}
$('#today').textContent=new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'});
function card(b,c){return `<article class="bird" tabindex="0" role="button" data-bird="${b.id}" aria-label="Record a ${b.name} sighting"><div class="bird-img"><img src="${photo(b)}" alt="Bird in its natural habitat" loading="lazy"><span class="badge ${b.rarity}">● ${b.rarity}</span></div><div class="bird-body"><h3>${b.name}</h3><div class="latin">${b.latin}</div><div class="bird-bottom"><span>⌖ ${c?esc(c.place):b.habitat}</span><span>${c?esc(new Date(c.date).toLocaleDateString()):'Discover ↗'}</span></div></div></article>`}$('#bird-grid').innerHTML=birds.slice(0,3).map(b=>card(b)).join('');
function navigate(v){document.querySelectorAll('.view').forEach(e=>e.hidden=e.id!==v);document.querySelectorAll('nav button').forEach(e=>e.classList.toggle('active',e.dataset.view===v));$('#page-name').textContent={explore:'Explore',collection:'My collection',journal:'Field journal'}[v];render();window.scrollTo({top:0,behavior:'smooth'})}document.querySelectorAll('nav button').forEach(e=>e.onclick=()=>navigate(e.dataset.view));
function render(){const total=catches.length,unique=new Set(catches.map(c=>c.bird)).size,xp=catches.reduce((n,c)=>n+(birds.find(b=>b.id===c.bird)?.xp||0),0);$('#total').innerHTML=`${total} <em>and counting</em>`;$('#species').innerHTML=`${unique} <em>new perspectives</em>`;$('#rare').innerHTML=`${catches.filter(c=>birds.find(b=>b.id===c.bird)?.rarity==='Rare').length} <em>little wonders</em>`;$('#places').innerHTML=`${new Set(catches.map(c=>c.place)).size} <em>go a little further</em>`;$('#nav-count').textContent=total;$('#level').textContent=`Level ${1+Math.floor(xp/250)} · ${xp} XP`;$('#xp').style.width=(xp%250)/2.5+'%';let rows=catches.filter(c=>{const b=birds.find(b=>b.id===c.bird);return b&&b.name.toLowerCase().includes($('#search').value.toLowerCase())&&($('#rarity-filter').value==='All rarities'||b.rarity===$('#rarity-filter').value)});$('#collection-grid').innerHTML=rows.length?rows.map(c=>card(birds.find(b=>b.id===c.bird),c)).join(''):`<div class="empty"><h2>${total?'No matching birds':'Your flock starts with one bird.'}</h2><p>${total?'Try a different search or rarity.':'Step outside, listen, and log your first encounter.'}</p><button class="primary listen-open">＋ Record a discovery</button></div>`;$('#journal-list').innerHTML=catches.length?catches.map(c=>{let b=birds.find(b=>b.id===c.bird);if(!b)return '';return `<article class="entry"><img src="${photo(b)}" alt="Bird"><div><h3>${b.name} <span class="badge ${b.rarity}">${b.rarity}</span></h3><p>${fmt(c.date)} · ⌖ ${esc(c.place)}</p>${c.coords?`<p>${c.coords.lat.toFixed(5)}, ${c.coords.lon.toFixed(5)}</p>`:''}<p>${esc(c.notes)}</p>${c.confidence!=null?`<p>BirdNET · ${(c.confidence*100).toFixed(1)}% confidence</p>`:''}</div><button class="delete" data-delete="${c.id}">Delete</button></article>`}).join(''):`<div class="empty"><h2>A fresh page. A whole world outside.</h2><p>Your sightings will appear here with their date, time, and location.</p><button class="primary listen-open">Log your first bird</button></div>`}
$('#search').oninput=render;$('#rarity-filter').onchange=render;document.addEventListener('click',e=>{let c=e.target.closest('[data-bird]');if(c)openCapture(c.dataset.bird);if(e.target.closest('.listen-open'))openCapture();let d=e.target.closest('[data-delete]');if(d){catches=catches.filter(c=>c.id!==d.dataset.delete);persist();toast('Sighting removed.')}});document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-bird]')){e.preventDefault();openCapture(e.target.dataset.bird)}});
function openCapture(){resetIdentification();$('#capture').showModal()}function stopTracks(){stream?.getTracks().forEach(t=>t.stop());stream=null}function stopRecording(){if(recorder?.state==='recording')recorder.stop();recording=false;stopTracks();$('#orb').classList.remove('live');$('#record').hidden=false;$('#stop').hidden=true}$('#capture .close').onclick=()=>$('#capture').close();$('#capture').addEventListener('close',stopRecording);$('#capture').addEventListener('cancel',stopRecording);
let audioBlob=null, captureGeneration=0, captureTimer=null, captureStarted=null, pendingMic=false;
function resetIdentification(){captureGeneration++; audioBlob=null;window.birdMatches=[];$('#bird-select').innerHTML='<option>Record a call to identify a bird</option>';$('#bird-select').disabled=true;$('#save').disabled=true;$('#retry-ai').hidden=true;$('#ai-detail').textContent='';$('#playback').hidden=true;$('#record-status').textContent='Record at least 3 seconds of clear birdsong.'}
async function identify(blob,generation){$('#record').disabled=true;$('#retry-ai').hidden=true;$('#record-status').textContent='Identifying birdsong…';try{let predictions=await BirdRecognition.identify(blob,p=>{if(generation===captureGeneration)$('#record-status').textContent=p});if(generation!==captureGeneration||!$('#capture').open)return;window.birdMatches=predictions;$('#bird-select').innerHTML=predictions.length?predictions.map((p,i)=>`<option value="${i}">${esc(p.commonName)} · ${(p.confidence*100).toFixed(1)}% confidence</option>`).join(''):'<option>No confident match</option>';$('#bird-select').disabled=!predictions.length;$('#save').disabled=!predictions.length;$('#record-status').textContent=predictions.length?'BirdNET found possible matches. Review before collecting.':'No confident bird detected. Try a clearer recording.';$('#ai-detail').textContent=predictions.length?'Model scores are not a guarantee of identification.':'No catch was created.'}catch(e){if(generation!==captureGeneration)return;$('#record-status').textContent=e.message;$('#retry-ai').hidden=false}finally{if(generation===captureGeneration)$('#record').disabled=false}}
$('#retry-ai').onclick=()=>{if(audioBlob)identify(audioBlob,captureGeneration)};
$('#record').onclick=async()=>{if(pendingMic)return;if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('Microphone recording is unavailable in this browser.');return}resetIdentification();const generation=captureGeneration;pendingMic=true;$('#record').disabled=true;try{const acquired=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:false,noiseSuppression:false,autoGainControl:false}});if(!$('#capture').open||generation!==captureGeneration){acquired.getTracks().forEach(t=>t.stop());return}stream=acquired;let chunks=[];const current=new MediaRecorder(stream);recorder=current;current.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};current.onstop=()=>{clearTimeout(captureTimer);if(generation!==captureGeneration||!$('#capture').open)return;if(audioUrl)URL.revokeObjectURL(audioUrl);audioBlob=new Blob(chunks,{type:current.mimeType});audioUrl=URL.createObjectURL(audioBlob);$('#playback').src=audioUrl;$('#playback').hidden=false;if(Date.now()-captureStarted<3000){$('#record-status').textContent='Too short. Record at least 3 seconds of birdsong.';return}identify(audioBlob,generation)};current.start();captureStarted=Date.now();recording=true;$('#record').hidden=true;$('#stop').hidden=false;$('#orb').classList.add('live');$('#record-status').textContent='Listening… recording stops after 12 seconds.';captureTimer=setTimeout(stopRecording,12000)}catch(e){stopTracks();const detail=e.name==='NotAllowedError'?'Microphone permission denied. Open Android Settings → Apps → Birdquest → Permissions → Microphone and allow access. Also check the phone’s Microphone access privacy switch.':e.name==='NotReadableError'?'Microphone is busy or blocked by Android. Close other recording apps and check the Microphone access privacy switch.':'Recording failed: '+e.name+' — '+e.message;$('#record-status').textContent=detail;toast(detail)}finally{pendingMic=false;$('#record').disabled=false}};$('#stop').onclick=stopRecording;
$('#capture').addEventListener('close',()=>{clearTimeout(captureTimer);captureGeneration++;$('#record').disabled=false});
function locate(){if(!navigator.geolocation){toast('Location is unavailable. Enter a place manually.');return}toast('Finding your location…');navigator.geolocation.getCurrentPosition(p=>{coords={lat:p.coords.latitude,lon:p.coords.longitude};$('#place').value=`${coords.lat.toFixed(5)}, ${coords.lon.toFixed(5)}`;$('#location span').textContent='Location enabled';toast('Coordinates captured for your next sighting.')},()=>toast('Location unavailable. Enter a place or habitat manually.'),{timeout:12000,maximumAge:60000,enableHighAccuracy:true})}$('#location').onclick=locate;$('#modal-location').onclick=locate;
function persist(){try{localStorage.setItem('birdquest-v1',JSON.stringify(catches));render();return true}catch{toast('Browser storage is full or unavailable. Export your journal to keep a copy.');return false}}$('#save').onclick=()=>{let place=$('#place').value.trim();if(!place){$('#place').focus();toast('Add a location or habitat for this sighting.');return}const match=window.birdMatches?.[Number($('#bird-select').value)];if(!match||recording||$('#save').disabled){toast('Record a bird call and wait for identification first.');return}let b=birds.find(b=>b.latin===match.scientificName);if(!b){b={id:'birdnet-'+match.scientificName.toLowerCase().replace(/[^a-z0-9]+/g,'-'),name:match.commonName,latin:match.scientificName,rarity:'Unrated',habitat:'BirdNET discovery',photo:null,xp:25};birds.push(b)}const c={id:crypto.randomUUID(),bird:b.id,date:new Date(captureStarted||Date.now()).toISOString(),place,coords:coords&&place===`${coords.lat.toFixed(5)}, ${coords.lon.toFixed(5)}`?coords:null,notes:$('#notes').value.trim(),identification:'BirdNET',confidence:match.confidence,speciesData:b,model:'BirdNET Live TFJS'};catches.unshift(c);if(!persist()){catches.shift();return}$('#capture').close();$('#notes').value='';toast(`${b.name} collected! +${b.xp} XP`)};
$('#export').onclick=()=>{if(!catches.length){toast('Log a sighting before exporting.');return}let q=s=>'"'+String(s??'').replace(/"/g,'""')+'"';let csv=[['Species','Scientific name','Rarity (game tier)','Date (UTC)','Location','Latitude','Longitude','Notes','Identification','Model confidence'],...catches.map(c=>{let b=birds.find(b=>b.id===c.bird);return[b.name,b.latin,b.rarity,c.date,c.place,c.coords?.lat,c.coords?.lon,c.notes,c.identification,c.confidence??'']})].map(r=>r.map(v=>q(/^[=+@\-\t\r]/.test(String(v??''))?"'"+v:v)).join(',')).join('\r\n');if(window.BirdquestAndroid?.postMessage){window.BirdquestAndroid.postMessage(JSON.stringify({type:'export-csv',csv}));return}let url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'})),a=document.createElement('a');a.href=url;a.download='birdquest-sightings.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};render();

function suspendCapture(){captureGeneration++;clearTimeout(captureTimer);stopRecording();if($('#capture').open)$('#capture').close();$('#playback').pause();}
document.addEventListener('visibilitychange',()=>{if(document.hidden&&!pendingMic)suspendCapture()});
window.addEventListener('birdquest-background',suspendCapture);
window.addEventListener('pagehide',suspendCapture);
